async function callExaAPI(url, payload) {
    if (!exaApiKey) {
        throw new Error("Hiányzó Exa API kulcs. Kérjük, adja meg az 'exaApiKey' változóban.");
    }
    const maxRetries = 3;
    let delay = 1000;
    for (let i = 0; i < maxRetries; i++) {
        try {
            const response = await fetch(url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'x-api-key': exaApiKey },
                body: JSON.stringify(payload)
            });
            if (!response.ok) {
                let errorBody = {};
                try { errorBody = await response.json(); } catch(e) {}
                throw new Error(`API hiba (${response.status}): ${errorBody.error || 'Ismeretlen hiba'}`);
            }
            const result = await response.json();
            if (result.answer || result.results) {
                return result;
            } else if (result.error) {
                throw new Error(`API válasz hiba: ${result.error}`);
            } else {
                throw new Error('Érvénytelen válasz a szervertől.');
            }
        } catch (error) {
            if (i === maxRetries - 1) throw error;
            await new Promise(resolve => setTimeout(resolve, delay));
            delay *= 2;
        }
    }
}
function formatExaAnswer(response) {
    const safeAnswer = escapeHtml(response.answer || "");
    let html = `<p>${safeAnswer}</p>`;
    if (response.citations && response.citations.length > 0) {
        html += `<div class="citations"><h4>Források:</h4><ul>`;
        response.citations.forEach(citation => {
            const t = citation.title ? escapeHtml(citation.title) : citation.url;
            html += `<li>${t}</li>`;
        });
        html += `</ul></div>`;
    }
    return html;
}
function formatExaResults(results, title) {
    if (!results || results.length === 0) {
        return `<p>Nincsenek találatok.</p>`;
    }
    let html = `<div class="citations"><h4>${escapeHtml(title)}:</h4><ul>`;
    results.forEach(result => {
        const t = result.title ? escapeHtml(result.title) : result.url;
        html += `<li>${t}</li>`;
    });
    html += `</ul></div>`;
    return html;
}
