async function startExaResearchTask(goal) {
    const tempTaskId = `temp_${Date.now()}`;
    addResearchWidgetToHistory(tempTaskId, goal, "Indítás...", 0);
    if (!exaApiKey) {
        updateResearchWidget(tempTaskId, { status: "❌ Hiba: Hiányzó Exa API kulcs.", progress: 0 });
        return;
    }
    try {
        const response = await fetch(exaResearchBaseUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'x-api-key': exaApiKey },
            body: JSON.stringify({ instructions: goal, model: 'exa-research' })
        });
        if (!response.ok) {
            let errorBody = {};
            try { errorBody = await response.json(); } catch(e) {}
            throw new Error(`API hiba (${response.status}): ${errorBody.error || 'Ismeretlen hiba'}`);
        }
        const exaTask = await response.json();
        const taskId = exaTask.researchId;
        researchTasks[taskId] = {
            id: taskId,
            goal: goal,
            status: exaTask.status,
            statusText: "Inicializálás...",
            progress: 5,
            subAgents: [{ name: 'Kutató Agent', status: 'Inicializálás...', progress: 5 }],
            similarLinks: [],
            webset: [],
            report: "",
            pollInterval: null
        };
        updateResearchWidgetId(tempTaskId, taskId);
        updateResearchWidget(taskId);
        pollResearchStatus(taskId);
    } catch (error) {
        updateResearchWidget(tempTaskId, { status: `❌ Hiba a feladat indításakor: ${error.message || String(error)}`, progress: 0 });
    }
