function pollResearchStatus(taskId) {
    const task = researchTasks[taskId];
    if (!task) return;
    if (task.pollInterval) clearInterval(task.pollInterval);
    task.pollInterval = setInterval(async () => {
        if (task.progress >= 100) {
            clearInterval(task.pollInterval);
            return;
        }
        try {
            const response = await fetch(`${exaResearchBaseUrl}/${taskId}?events=true`, { headers: { 'x-api-key': exaApiKey } });
            if (!response.ok) {
                throw new Error(`API hiba (${response.status})`);
            }
            const exaTask = await response.json();
            task.status = exaTask.status;
            if (exaTask.status === 'running') {
                task.progress = Math.min(95, (task.progress || 0) + 5);
                if (exaTask.events && exaTask.events.length > 0) {
                    const last = exaTask.events[exaTask.events.length - 1];
