                task.statusText = "Befejezve";
                task.report = exaTask.output || "";
                const citations = exaTask.citations || [];
                task.similarLinks = citations.map(c => ({ title: c.title, url: c.url }));
                task.webset = citations.map(c => ({ title: c.title, url: c.url, category: 'Forrás' }));
                task.subAgents = task.subAgents.map(a => ({ ...a, progress: 100, status: 'Befejezve' }));
            } else if (exaTask.status === 'failed') {
                clearInterval(task.pollInterval);
                task.progress = 100;
                task.status = 'failed';
                task.statusText = `❌ Hiba: ${exaTask.error || 'Ismeretlen hiba'}`;
                task.report = `A feladat sikertelen: ${exaTask.error || 'Részletek nem elérhetők.'}`;
                task.subAgents = [{ name: 'Agent', status: 'Sikertelen', progress: 100 }];
